mapper.select:
SELECT DISTINCT room_id
  FROM mvc_chat6
 WHERE sender = #{userId}
    OR receiver = #{userId}

SELECT * FROM ( SELECT m.*, ROW_NUMBER() OVER (PARTITION BY room_id ORDER BY regdate DESC, regtime DESC) AS rn FROM mvc_chat6 m WHERE m.room_id IN ( SELECT room_id FROM mvc_chat6 WHERE sender = #{userId} OR receiver = #{userId} )
AND ( content LIKE '%' || #{searchText} || '%' OR receiver LIKE '%' || #{searchText} || '%' OR sender LIKE '%' || #{searchText} || '%' )
) WHERE rn = 1 ORDER BY regdate DESC, regtime DESC

choose.when:
		SELECT DISTINCT receiver
  		  FROM mvc_chat6
 		 WHERE room_id = #{roomId}
 		 AND receiver != #{userId}

choose.otherwise:
		SELECT DISTINCT sender
  		  FROM mvc_chat6
 		 WHERE room_id = #{roomId}
 		   AND sender != #{userId}

